function fmtArgent(n) { return Math.round(n).toLocaleString("fr-CA") + " $"; }
function fvMensuel(pmt, tauxAnnuel, annees) { const r = tauxAnnuel / 12, n = Math.round(annees * 12); return r > 0 ? pmt * (Math.pow(1 + r, n) - 1) / r : pmt * n; }

